<template><section class="page-shell"><header class="page-heading"><div><p class="eyebrow">SEU ACESSO</p><h1>Minha conta</h1><p>{{user.user?.name}}</p></div><button v-if="user.user" class="secondary" @click="logout">Sair da conta</button></header><p v-if="!user.user">Entre na sua conta para continuar. <router-link to="/RegisterAndLogin?mode=login">Entrar</router-link></p><template v-else><div class="account-grid"><section class="panel"><h2>Assinatura</h2><p :class="user.hasActiveSubscription?'success':'muted'">{{user.hasActiveSubscription?'Ativa':'Inativa ou expirada'}}</p><p v-if="user.user.subscriptionEnd">Validade: {{dateOf(user.user.subscriptionEnd).toLocaleDateString('pt-BR')}}</p><p v-if="user.daysRemaining">{{user.daysRemaining}} dias restantes</p><p v-if="user.daysRemaining>0 && user.daysRemaining<=7" class="notice">Sua assinatura está perto do vencimento.</p><form @submit.prevent="activate"><label>Chave de ativação<input v-model="key" required maxlength="128" autocomplete="off"></label><button class="primary" :disabled="busy">Ativar ou renovar</button></form><p class="muted">A renovação preserva os dias que você já possui. Cada chave pode ser usada uma vez.</p><div class="actions"><button class="secondary" @click="checkout" :disabled="busy">Pagar online</button><a class="secondary" href="https://wa.me/5586995102595?text=Quero%20renovar%20minha%20assinatura" target="_blank" rel="noopener">Solicitar pelo WhatsApp</a></div></section><section class="panel"><h2>Meu perfil</h2><form @submit.prevent="save"><label>Nome<input v-model="firstName" required maxlength="80"></label><label>Sobrenome<input v-model="lastName" maxlength="100"></label><label>Telefone<input v-model="numero" type="tel" maxlength="25"></label><label>E-mail<input :value="user.user.email" readonly type="email"></label><div class="actions"><button class="primary" :disabled="busy">Salvar perfil</button><button type="button" class="secondary" @click="resetPassword">Recuperar senha</button></div></form></section></div><p role="status" class="status-message">{{message}}</p><section class="panel"><h2>Preferências</h2><label class="check"><input type="checkbox" v-model="economy" @change="preferences"> Economia de dados (menos imagens e nenhum áudio pré-carregado)</label><label class="check"><input type="checkbox" v-model="effects" @change="preferences"> Efeitos visuais</label><button class="secondary" @click="install">Instalar aplicativo</button><p class="muted">Se a instalação não estiver disponível, use “Adicionar à tela inicial” no menu do navegador. O aplicativo precisa de conexão para acessar músicas e conta.</p></section><section class="panel"><h2>Avisos e novidades</h2><p v-if="!notifications.length && !user.user.messages?.length">Nenhum aviso no momento.</p><article v-for="(msg,index) in user.user.messages || []" :key="`legacy-${index}`" class="queue-row">{{msg}}</article><article v-for="n in notifications" :key="n.id" class="queue-row">{{n.message}} <small>{{dateOf(n.createdAt).toLocaleDateString('pt-BR')}}</small></article></section><section class="panel"><h2>Histórico de downloads solicitados</h2><p class="muted">O histórico registra pedidos e autorizações, não a conclusão do download no aparelho.</p><p v-if="!history.length">Nenhum pedido registrado.</p><article v-for="d in history" :key="d.id" class="queue-row"><div><strong>{{d.title || `Pacote de ${d.ids?.length || 0} músicas`}}</strong><small>{{dateOf(d.at).toLocaleString('pt-BR')}} · {{bytes(d.bytes)}} · {{statusLabel(d.status)}}</small></div><button v-if="d.packageId" class="secondary" @click="checkPackage(d)">Consultar / baixar</button></article></section></template></section></template>
<script setup>
import {ref,watch,onBeforeUnmount} from 'vue'
import {useRouter} from 'vue-router'
import {sendPasswordResetEmail,updateProfile} from 'firebase/auth'
import {doc,updateDoc,collection,query,where,onSnapshot} from 'firebase/firestore'
import {auth,db} from '@/firebase'
import {useUserStore} from '@/stores/userStore'
import {api} from '@/services/api'
import {dateOf,bytes} from '@/utils/catalog'
const user=useUserStore(),router=useRouter(),firstName=ref(''),lastName=ref(''),numero=ref(''),key=ref(''),busy=ref(false),message=ref(''),history=ref([]),notifications=ref([]),economy=ref(localStorage.getItem('repertorio:economy')==='true'),effects=ref(localStorage.getItem('repertorio:effects')!=='false');let unsubHistory,unsubNotifications
watch(()=>user.user?.uid,uid=>{unsubHistory?.();unsubNotifications?.();history.value=[];notifications.value=[];if(!uid)return;firstName.value=user.user.firstName || '';lastName.value=user.user.lastName || '';numero.value=user.user.numero || '';unsubHistory=onSnapshot(query(collection(db,'downloads'),where('uid','==',uid)),s=>history.value=s.docs.map(d=>({...d.data(),id:d.id})).sort((a,b)=>dateOf(b.at)-dateOf(a.at)).slice(0,100),()=>message.value='Não foi possível carregar o histórico.');unsubNotifications=onSnapshot(collection(db,'notifications'),s=>notifications.value=s.docs.map(d=>({...d.data(),id:d.id})).sort((a,b)=>dateOf(b.createdAt)-dateOf(a.createdAt)).slice(0,30))},{immediate:true})
watch(()=>user.loadingUser,loading=>{if(!loading && user.user){firstName.value=user.user.firstName || '';lastName.value=user.user.lastName || '';numero.value=user.user.numero || ''}},{immediate:true})
async function run(fn){busy.value=true;message.value='';try{await fn()}catch(e){message.value=e.message}finally{busy.value=false}}
function activate(){run(async()=>{message.value=await user.ativarAssinaturaComChave(key.value.trim());key.value=''})}
function save(){run(async()=>{await updateDoc(doc(db,'users',user.user.uid),{firstName:firstName.value.trim(),lastName:lastName.value.trim(),numero:numero.value.trim()});await updateProfile(auth.currentUser,{displayName:firstName.value.trim()});message.value='Perfil atualizado.'})}
function resetPassword(){run(async()=>{await sendPasswordResetEmail(auth,user.user.email);message.value='Solicitação enviada. Confira o e-mail de recuperação.'})}
function checkout(){run(async()=>{const {url}=await api('checkout');window.location.assign(url)})}
async function checkPackage(d){run(async()=>{const result=await api('package-status',{id:d.packageId});if(result.url){const a=document.createElement('a');a.href=result.url;a.click();message.value='Download autorizado.'}else message.value=result.status==='failed'?'A preparação falhou. Avise o suporte.':'Pacote em preparação. Consulte novamente mais tarde.'})}
function preferences(){localStorage.setItem('repertorio:economy',economy.value);localStorage.setItem('repertorio:effects',effects.value);document.documentElement.classList.toggle('data-economy',economy.value);document.documentElement.classList.toggle('reduced-effects',!effects.value)}
async function install(){if(window.repertorioInstallPrompt){await window.repertorioInstallPrompt.prompt();window.repertorioInstallPrompt=null}else message.value='Use “Instalar aplicativo” ou “Adicionar à tela inicial” no menu do navegador.'}
async function logout(){await user.logout();router.push('/')}
function statusLabel(s){return ({authorized:'Autorizado',pending:'Em preparação',ready:'Disponível',failed:'Falha na preparação'})[s] || s}
onBeforeUnmount(()=>{unsubHistory?.();unsubNotifications?.()})
</script>
